'use strict';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',tower:'<path d="M12 3 5 21h14L12 3ZM8 13h8M7 17h10M10 8h4M9 17l6-4M9 13l6 4"/><path d="M5 4a6 6 0 0 0-2 5M19 4a6 6 0 0 1 2 5"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',check:'<path d="m5 12 4 4L19 6"/>',clipboard:'<rect x="5" y="5" width="14" height="16" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="m9 14 2 2 4-4"/>',camera:'<path d="m8 5 2-2h4l2 2h4a2 2 0 0 1 2 2v12H2V7a2 2 0 0 1 2-2h4Z"/><circle cx="12" cy="12" r="4"/>',folder:'<path d="M3 7V4h7l2 3h9v13H3V7Z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M17 5a3 3 0 0 1 0 6M18 15a4 4 0 0 1 3 4v2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 2 3-1 2 4 3-1 1-3 3-1 2-3-2-2 1-4-3-2-3 1-2-4-3 1Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3V9ZM9 21h6"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',export:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3l-1 2M12 17h.01"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 15v6h16v-6"/>',file:'<path d="M5 3h9l5 5v13H5V3Zm9 0v6h5M9 13h6M9 17h6"/>',shield:'<path d="M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6L12 2Z"/><path d="m8 12 3 3 5-6"/>',electric:'<path d="m13 2-9 12h7l-1 8 10-13h-8l1-7Z"/>',home:'<path d="m3 10 9-8 9 8v11h-6v-8H9v8H3V10Z"/>',back:'<path d="M20 12H5m5-5-5 5 5 5"/>',chart:'<path d="M4 20h17M7 16V9M12 16V3M17 16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const I=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const statusColor={'In progress':'green','Awaiting review':'orange','Approved':'blue','Draft':'gray','Changes requested':'red'};
const badge=s=>`<span class="tag ${statusColor[s]||'gray'}"><span class="dot"></span>${E(s)}</span>`;
const blankChecks=()=>({access:false,foundation:false,corrosion:false,earthing:false,clearance:false,labels:false});
const seeds=()=>[
 ['DEMO-10452','Riyadh · Central','In progress',68,'Project engineer','Telecom survey','Tower'],
 ['DEMO-10461','Riyadh · Central','Awaiting review',100,'Field engineer 01','Telecom survey','Rooftop'],
 ['DEMO-10502','Riyadh · Central','In progress',42,'Project engineer','Telecom survey','Tower'],
 ['DEMO-10518','Riyadh · Central','Approved',100,'Field engineer 02','Telecom survey','Tower'],
 ['DEMO-10524','Riyadh · Central','Draft',12,'Project engineer','Telecom survey','Rooftop'],
 ['DEMO-10531','Riyadh · Central','Awaiting review',100,'Field engineer 01','Telecom survey','Tower'],
 ['DEMO-10547','Riyadh · Central','In progress',76,'Field engineer 02','Telecom survey','Tower'],
 ['DEMO-10556','Riyadh · Central','Approved',100,'Project engineer','Telecom survey','Tower'],
 ['DEMO-10563','Riyadh · Central','Awaiting review',100,'Field engineer 02','Network expansion','Tower'],
 ['DEMO-10579','Riyadh · Central','In progress',35,'Project engineer','Network expansion','Rooftop'],
 ['DEMO-10582','Riyadh · Central','Approved',100,'Field engineer 01','Network expansion','Tower'],
 ['DEMO-10590','Riyadh · Central','Draft',0,'Field engineer 02','Network expansion','Tower']
].map((s,i)=>({id:s[0],location:s[1],status:s[2],progress:s[3],engineer:s[4],project:s[5],type:s[6],lat:(24.66+i*.0062).toFixed(6),lon:(46.65+i*.007).toFixed(6),due:'18 Oct',created:'15 Oct',answers:{siteName:s[0],siteType:s[6],operator:'STC',towerHeight:'40',access:'Accessible',surveyDate:'2026-10-15',voltage:'400',currentR:'',currentY:'',currentB:'',dcVoltage:'48',powerSource:'Grid supply',civilNotes:'',electricalNotes:'',powerNotes:'',generalNotes:'',capacity:'',battery:'',solar:'Not installed',generator:'Not installed'},checks:blankChecks(),equipment:[{model:'Sample panel antenna',dimensions:'1.80 × 0.35 × 0.15',height:'32',azimuth:'120',sector:'2'}],photos:[],comments:[]}));
let data;try{data=JSON.parse(localStorage.getItem('isurvix-redesign-v1'))}catch{}if(!data?.sites||!Array.isArray(data.sites))data={sites:seeds(),activities:[],settings:{compact:false,notifications:true}};
let view='overview',role='Team leader',selected=data.sites[0].id,section='general',siteFilter='All',siteSearch='',listMode='list',overviewTab='Active',mapSelected=data.sites[0].id,photoFilter='All',saveTimer=null,menuOpen=false;
const site=()=>data.sites.find(x=>x.id===selected)||data.sites[0];
const visibleSites=()=>role==='Engineer'?data.sites.filter(x=>x.engineer==='Project engineer'):data.sites;
const navItems=[['overview','grid','Overview'],['sites','tower','My sites'],['map','pin','Network map'],['review','clipboard','Review queue'],['photos','camera','Photo library'],['reports','file','Reports']];
const sections=[['general','file','General information'],['civil','home','Civil & site'],['electrical','electric','Electrical'],['power','sun','Power systems'],['equipment','tower','Tower equipment'],['evidence','camera','Photo evidence'],['submission','shield','Review & submit']];
function persist(){try{localStorage.setItem('isurvix-redesign-v1',JSON.stringify(data));return true}catch{toast('Device storage is full. Remove some uploaded photos and try again.');return false}}
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('visible'),3500)}
function addActivity(text,type='check'){data.activities.unshift({text,type,time:'Just now'});data.activities=data.activities.slice(0,12);persist()}
function title(t,p,actions=''){return `<div class="page-title"><div><h1>${t}</h1><p>${p}</p></div><div class="title-actions">${actions}</div></div>`}
function go(v){view=v;menuOpen=false;render();window.scrollTo({top:0,behavior:'instant'})}
function openSite(id,part='general'){selected=id;section=part;go('workspace')}
function render(){if(view==='website'){document.getElementById('app').innerHTML=marketing();return}
 const counts=data.sites.filter(s=>s.status==='Awaiting review').length;
 document.getElementById('app').innerHTML=`<div class="mobile-overlay ${menuOpen?'visible':''}" onclick="toggleMenu(false)"></div><aside class="sidebar ${menuOpen?'open':''}"><a class="brand" href="#" onclick="go('overview');return false"><div><img src="assets/logo-latest.png" alt="iSurvix"><small>SURVEY WORKSPACE</small></div></a><button class="workspace-select" onclick="go('projects')"><span class="workspace-icon">${I('folder')}</span><span class="grow"><strong>Telecom survey</strong><small>Demo workspace · KSA</small></span>${I('down')}</button><p class="navlabel">WORKSPACE</p><nav class="nav" aria-label="Main navigation">${navItems.map(([v,i,n])=>`<button class="${view===v||(view==='workspace'&&v==='sites')?'active':''}" onclick="go('${v}')">${I(i)}${n}${v==='review'&&counts?`<span class="count">${counts}</span>`:''}</button>`).join('')}</nav><p class="navlabel nav-sep">MANAGEMENT</p><nav class="nav" aria-label="Management">${[['projects','folder','Projects'],['team','users','Team & roles'],['builder','clipboard','Checklist templates'],['settings','settings','Settings']].filter(([v])=>v!=='builder'||role==='Admin').map(([v,i,n])=>`<button class="${view===v?'active':''}" onclick="go('${v}')">${I(i)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="helpbox">${I('help')}<strong>A clearer way to survey.</strong><p>Follow your site checklist from first visit to final approval.</p><button class="btn link" onclick="showGuide()">Quick start guide ${I('arrow')}</button></div><nav class="nav"><button onclick="go('website')">${I('external')}View public website</button></nav><div class="sidebar-user"><span class="avatar">${role==='Engineer'?'PE':role==='Admin'?'AD':'TL'}</span><div class="grow"><strong>${role==='Engineer'?'Project engineer':role==='Admin'?'Workspace admin':'Project team lead'}</strong><small>${E(role)} · Demo account</small></div>${I('down')}</div></div></aside><div class="shell"><header class="topbar"><button class="iconbtn mobile-toggle" aria-label="Open navigation" onclick="toggleMenu()">${I('menu')}</button><div class="breadcrumb">Workspace <span style="margin-left:10px;color:#bac2b1">/</span><b>${view==='workspace'?'My sites / '+E(site().id):({overview:'Overview',sites:'My sites',map:'Network map',review:'Review queue',photos:'Photo library',reports:'Reports',projects:'Projects',team:'Team & roles',settings:'Settings',builder:'Checklist templates'}[view]||'Overview')}</b></div><div class="top-actions"><form class="searchbar" onsubmit="event.preventDefault();globalSearch(this.querySelector('input').value)">${I('search')}<input id="global-search" aria-label="Search sites" placeholder="Search sites, projects…"><kbd>⌘ K</kbd></form><select aria-label="Preview role" onchange="changeRole(this.value)">${['Team leader','Engineer','Admin'].map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select><button class="iconbtn notice-dot" aria-label="Notifications" onclick="showNotifications()">${I('bell')}</button><span style="height:23px;width:1px;background:var(--line)"></span><span class="avatar">${role==='Engineer'?'PE':role==='Admin'?'AD':'TL'}</span></div></header><main class="content"><div class="preview-banner"><span class="dot"></span>INTERACTIVE DESIGN PREVIEW <span style="color:#c0c8b3">/</span> Sample project data · explore all three roles</div>${({overview:overview,sites:sitesPage,map:mapPage,review:reviewPage,photos:photosPage,reports:reportsPage,projects:projectsPage,team:teamPage,settings:settingsPage,builder:builderPage,workspace:workspacePage}[view]||overview)()}<footer class="footer"><span>© 2026 iSurvix · Intelligent Survey Index</span><span>From field evidence to confident decisions.</span></footer></main></div>`;
}
function toggleMenu(v){menuOpen=typeof v==='boolean'?v:!menuOpen;document.querySelector('.sidebar')?.classList.toggle('open',menuOpen);document.querySelector('.mobile-overlay')?.classList.toggle('visible',menuOpen)}
function changeRole(r){role=r;if(view==='workspace'&&r==='Engineer'&&site().engineer!=='Project engineer')view='sites';render();toast(`Now exploring the ${r.toLowerCase()} dashboard`)}
function globalSearch(q){siteSearch=q;siteFilter='All';go('sites')}
function stats(){const ss=visibleSites();return [['tower','Assigned sites',ss.length,'Sites in your workspace','All sample data'],['clock','In progress',ss.filter(x=>x.status==='In progress').length,'Active site surveys','Continue your fieldwork'],['clipboard','Awaiting review',ss.filter(x=>x.status==='Awaiting review').length,'Ready for a decision','Review before approval'],['shield','Approved',ss.filter(x=>x.status==='Approved').length,'Survey records finalized','Evidence and report ready']]}
function overview(){const ss=visibleSites();const waiting=ss.filter(s=>s.status==='Awaiting review').length;let rows=overviewTab==='All sites'?ss:overviewTab==='Review'?ss.filter(s=>s.status==='Awaiting review'):ss.filter(s=>s.status!=='Approved');return `${title('Your fieldwork, in focus.','A clear view of your sites, survey progress, and next actions.',`<button class="btn" onclick="exportSites()">${I('export')}Export CSV</button><button class="btn primary" onclick="newSite()">${I('plus')}New site</button>`)}<div class="metrics">${stats().map(([i,t,n,foot,sub])=>`<div class="metric"><div class="metric-top"><span>${t}</span>${I(i)}</div><div class="metric-num num">${n.toString().padStart(2,'0')}</div><div class="metric-foot"><b>${foot}</b></div><div class="metric-foot" style="margin-top:5px">${sub}</div></div>`).join('')}</div><div class="dashboard-grid"><div><div class="focus"><div><div class="eyebrow">YOUR NEXT ACTION</div><h3>${role==='Engineer'?'Pick up where you left off.':waiting+' submissions need your review.'}</h3><p>${role==='Engineer'?'DEMO-10452 is ready for its next checklist section. Keep your evidence organized as you go.':'Check the submitted survey evidence, leave feedback, and move your sites forward.'}</p></div><button class="btn" onclick="${role==='Engineer'?`openSite('${ss.find(x=>x.status==='In progress')?.id||ss[0]?.id}')`:`go('review')`}">${role==='Engineer'?'Continue survey':'Open review queue'} ${I('arrow')}</button></div><section class="card"><div class="card-head"><div><h2>Your sites</h2><p>Keep every survey moving in the right direction.</p></div><button class="btn link" onclick="go('sites')">View all ${I('arrow')}</button></div><div class="panel-tabs">${['Active','Review','All sites'].map(t=>`<button class="${overviewTab===t?'active':''}" onclick="overviewTab='${t}';render()">${t}${t==='Active'?` <span class="tag gray">${ss.filter(x=>x.status!=='Approved').length}</span>`:''}</button>`).join('')}</div>${siteTable(rows.slice(0,5),true)}<div class="card-foot"><span>Showing ${Math.min(rows.length,5)} of ${rows.length} sites</span><button class="btn link" onclick="go('sites')">Manage sites ${I('arrow')}</button></div></section></div><div class="right-column"><section class="card"><div class="card-head"><div><h2>Sites at a glance</h2><p>Central region · illustrative map</p></div><button class="iconbtn" aria-label="Open network map" onclick="go('map')">${I('external')}</button></div>${mapMarkup()}<div class="map-site"><span class="site-symbol">${I('tower')}</span><div class="grow"><strong>${E(mapSelected)}</strong><p>${E(data.sites.find(x=>x.id===mapSelected)?.location||'Central region')}</p></div><button class="iconbtn" aria-label="Open selected site" onclick="openSite('${E(mapSelected)}')">${I('chevron')}</button></div></section><section class="card"><div class="card-head"><h2>Recent activity</h2><span class="sample-marker">Sample timeline</span></div><div class="activity">${activityMarkup()}</div></section></div></div><div class="overview-bottom"><section class="card"><div class="card-head"><h2>Survey distribution</h2><span class="small muted">${ss.length} sites</span></div><div class="distribution"><div class="donut" style="background:${donutGradient(ss)}"><span>${ss.length}<small>Total sites</small></span></div><div class="legend">${[['Approved','#658f3f'],['In progress','#a4c875'],['Awaiting review','#f0e3c9'],['Draft','#dce8cb'],['Changes requested','#d4a08b']].map(([n,c])=>`<div><span><span class="square" style="background:${c}"></span>${n}</span><b>${ss.filter(x=>x.status===n).length}</b></div>`).join('')}</div></div></section><section class="card mini-info"><span class="big-icon">${I('clipboard')}</span><div><h3>One site. One clear record.</h3><p>Site details, checklist answers, photos, and review comments — connected in a single workspace.</p><button class="btn link" style="margin-top:10px;font-size:10px" onclick="openSite('${E(ss[0]?.id||data.sites[0].id)}')">Explore a site ${I('arrow')}</button></div></section></div>`}
function donutGradient(ss){let start=0;const colors={'Approved':'#658f3f','In progress':'#a4c875','Awaiting review':'#f0e3c9','Draft':'#dce8cb','Changes requested':'#d4a08b'};const stops=Object.entries(colors).map(([n,c])=>{const end=start+ss.filter(x=>x.status===n).length/(ss.length||1)*100;const s=`${c} ${start}% ${end}%`;start=end;return s});return `conic-gradient(${stops.join(',')})`}
function activityMarkup(){let a=[...data.activities,...[{text:'DEMO-10461 was submitted for review',type:'clipboard',time:'20 min ago'},{text:'DEMO-10518 survey was approved',type:'check',time:'1 hr ago'},{text:'Photo evidence added to DEMO-10452',type:'camera',time:'2 hrs ago'},{text:'DEMO-10524 assigned to project engineer',type:'users',time:'3 hrs ago'}]];return a.slice(0,4).map(x=>`<div class="activity-item"><span class="activity-icon">${I(x.type)}</span><div><p>${E(x.text)}</p><small>${E(x.time)}</small></div></div>`).join('')}
function siteTable(ss,short=false){return `<div class="table-wrap"><table><thead><tr><th>Site / Location</th><th>Status</th><th>Progress</th>${short?'':'<th>Assigned to</th><th>Project</th>'}<th></th></tr></thead><tbody>${ss.map(s=>`<tr><td><div class="row"><span class="site-symbol">${I('tower')}</span><div><div class="site-id">${E(s.id)}</div><div class="site-sub">${E(s.location)}</div></div></div></td><td>${badge(s.status)}</td><td><div class="progress-cell"><small><span>Checklist</span><span>${s.progress}%</span></small><div class="progress"><span style="width:${s.progress}%"></span></div></div></td>${short?'':`<td>${E(s.engineer)}</td><td>${E(s.project)}</td>`}<td><button class="table-action" aria-label="Open ${E(s.id)}" onclick="openSite('${E(s.id)}')">${I('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No sites match your filters.</td></tr>'}</tbody></table></div>`}
function mapMarkup(full=false){const positions=[[50,48],[34,30],[61,24],[69,66],[27,63],[79,40],[46,77],[18,39],[87,74],[55,12],[38,56],[73,17]];return `<div class="map ${full?'fullmap':''}"><svg class="basemap" viewBox="0 0 500 320" preserveAspectRatio="xMidYMid slice" aria-label="Illustrative site cluster map"><defs><pattern id="blocks" width="53" height="42" patternTransform="rotate(-16)" patternUnits="userSpaceOnUse"><rect width="53" height="42" fill="#eff1e8"/><rect x="5" y="5" width="18" height="12" rx="1" fill="#e3e8da"/><rect x="27" y="5" width="19" height="12" rx="1" fill="#e7eadf"/><rect x="5" y="22" width="40" height="13" rx="1" fill="#e4e9dc"/><path d="M0 0h53M0 0v42" stroke="#fff" stroke-width="4"/></pattern></defs><rect width="500" height="320" fill="url(#blocks)"/><path d="M-20 180C100 100 160 205 280 170S430 190 520 120" stroke="#dbe0d1" stroke-width="29" fill="none"/><path d="M-20 180C100 100 160 205 280 170S430 190 520 120" stroke="#fbfcf7" stroke-width="21" fill="none"/><path d="M215-20C245 70 260 140 305 220S390 280 420 340" stroke="#dce3d0" stroke-width="30" fill="none"/><path d="M215-20C245 70 260 140 305 220S390 280 420 340" stroke="#fbfcf7" stroke-width="22" fill="none"/><path d="M215-20C245 70 260 140 305 220S390 280 420 340" stroke="#e5dbc0" stroke-width="2" stroke-dasharray="6 4" fill="none"/><path d="M80-10 130 330M-20 275 490 28" stroke="#f8faf4" stroke-width="11"/><path d="M410-20 450 120 500 240" stroke="#d8e4c7" stroke-width="24" fill="none"/><text x="105" y="90" font-family="Arial" font-size="9" letter-spacing="2" fill="#a0ac8d">CENTRAL CLUSTER</text><text x="326" y="259" font-family="Arial" font-size="9" letter-spacing="2" fill="#a0ac8d">SURVEY ZONE</text></svg><span class="map-label">${I('pin')} ${visibleSites().length} sample sites</span>${visibleSites().map((s,i)=>`<button class="pin ${mapSelected===s.id?'active':''}" style="left:${positions[i%positions.length][0]}%;top:${positions[i%positions.length][1]}%" title="${E(s.id)} · ${E(s.status)}" aria-label="Select ${E(s.id)}" onclick="mapSelected='${E(s.id)}';render()">${i+1}</button>`).join('')}<span class="map-scale">Illustrative layout · not a navigation map</span></div>`}
function sitesPage(){let ss=visibleSites().filter(s=>(siteFilter==='All'||s.status===siteFilter)&&`${s.id} ${s.location} ${s.project}`.toLowerCase().includes(siteSearch.toLowerCase()));return `${title('Every site, connected.','Find a site, understand its status, and continue your survey.',`<button class="btn" onclick="exportSites()">${I('export')}Export CSV</button><button class="btn primary" onclick="newSite()">${I('plus')}New site</button>`)}<div class="filters"><div class="filter-buttons">${['All','In progress','Awaiting review','Approved','Draft'].map(t=>`<button class="${siteFilter===t?'active':''}" onclick="siteFilter='${t}';render()">${t}</button>`).join('')}</div><div class="row"><input class="filter-input" aria-label="Filter sites" placeholder="Search Site ID or project…" value="${E(siteSearch)}" oninput="filterSites(this.value)"><button class="iconbtn" aria-label="Toggle site card view" onclick="listMode=listMode==='list'?'grid':'list';render()">${I('grid')}</button></div></div>${listMode==='list'?`<section class="card">${siteTable(ss)}<div class="card-foot"><span>${ss.length} sites · Sample workspace</span><span class="keyboard-hint">Select a site to open its workspace</span></div></section>`:`<div class="sites-grid">${ss.map(siteCard).join('')||'<div class="empty">No sites match your search.</div>'}</div>`}`}
function filterSites(q){siteSearch=q;const active=document.activeElement;const at=active?.selectionStart;render();const field=document.querySelector('.filter-input');field?.focus();if(at!=null)field?.setSelectionRange(at,at)}
function siteCard(s){return `<article class="card site-card"><div class="row between"><span class="site-symbol">${I('tower')}</span>${badge(s.status)}</div><h3>${E(s.id)}</h3><p>${I('pin')} ${E(s.location)}</p><div class="mini-meta"><span><small>Assigned engineer</small>${E(s.engineer)}</span><span><small>Site type</small>${E(s.type)}</span></div><div class="row between small muted" style="margin-bottom:8px"><span>Survey completion</span><b>${s.progress}%</b></div><div class="progress"><span style="width:${s.progress}%"></span></div><div class="card-action"><span class="small muted">${E(s.project)}</span><button class="btn link" onclick="openSite('${E(s.id)}')">Open site ${I('arrow')}</button></div></article>`}
function mapPage(){const s=data.sites.find(x=>x.id===mapSelected)||data.sites[0];return `${title('Your network, in view.','Explore site clusters and jump straight into the survey record.')}<section class="card">${mapMarkup(true)}<div class="map-site"><span class="site-symbol">${I('tower')}</span><div class="grow"><strong>${E(s.id)}</strong><p>${E(s.location)} · ${E(s.lat)}, ${E(s.lon)}</p></div>${badge(s.status)}<button class="btn primary" onclick="openSite('${E(s.id)}')">Open workspace ${I('arrow')}</button></div></section><div class="small muted" style="margin-top:15px">Preview locations and map layout are illustrative. Actual coordinates will be used when connected to your survey database.</div>`}
function workspacePage(){const s=site(),locked=s.status==='Approved';if(s.templateSnapshot)return customWorkspacePage(s);return `<button class="back" onclick="go('sites')">${I('back')}Back to sites</button><section class="card site-hero"><div class="row"><span class="site-symbol">${I('tower')}</span><div><div class="row"><h1>${E(s.id)}</h1>${badge(s.status)}</div><p>${E(s.location)} <span style="margin:0 8px">·</span>${E(s.type)} site <span style="margin:0 8px">·</span>${E(s.project)}</p></div></div><div class="meta"><span><small>Assigned to</small>${E(s.engineer)}</span><span><small>Survey progress</small>${s.progress}% complete</span></div><button class="btn" onclick="downloadReport('${E(s.id)}')">${I('export')}Export CSV</button></section><div class="card stepbar">${[['Site assigned','done'],['Survey & evidence',s.status==='Draft'||s.status==='In progress'||s.status==='Changes requested'?'current':'done'],['Technical review',s.status==='Awaiting review'?'current':locked?'done':''],['Final approval',locked?'done':'']].map(([t,c],i)=>`${i?'<span class="step-line"></span>':''}<div class="step ${c}"><span class="step-num">${c==='done'?I('check'):i+1}</span>${t}</div>`).join('')}</div><div class="workspace-grid"><aside class="card sections"><div class="eyebrow">SITE CHECKLIST</div>${sections.map(([k,i,t])=>`<button class="${section===k?'active':''}" onclick="section='${k}';render()">${I(i)}${t}<span class="section-done">${k==='general'?I('check'):k==='evidence'?s.photos.length:''}</span></button>`).join('')}<div class="completion"><div class="row between"><span>Overall completion</span><b>${s.progress}%</b></div><div class="progress"><span style="width:${s.progress}%"></span></div></div></aside><section class="card"><div class="card-head"><div><h2>${sections.find(x=>x[0]===section)?.[2]||'General information'}</h2><p>${locked?'Approved record · view only':'Step '+(sections.findIndex(x=>x[0]===section)+1)+' of 7 · '+E(s.id)}</p></div><span id="save-state" class="save-state">${I(locked?'shield':'check')}${locked?'Finalized':'Saved on this device'}</span></div><div class="form-body">${workspaceForm(s,locked)}</div><div class="form-foot"><button class="btn" onclick="previousSection()">${I('back')}Previous</button><span class="keyboard-hint">${locked?'Approved records stay locked':'Your changes save as you work'}</span><button class="btn primary" onclick="nextSection()">${section==='submission'?'Back to overview':'Next section'}${I('arrow')}</button></div></section><aside class="site-aside"><section class="card"><div class="card-head"><h3>Site location</h3>${I('pin')}</div>${mapMarkup()}<div class="site-aside-content" style="padding-top:15px"><strong>${E(s.location)}</strong><br>${E(s.lat)}, ${E(s.lon)}<br>Illustrative preview coordinates</div></section><section class="card"><div class="card-head"><h3>Field guidance</h3>${I('help')}</div><div class="site-aside-content">${guidance(section)}<div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--line)"><strong>Keep evidence traceable.</strong><br>Assign each photo to its checklist section and review before submission.</div></div></section>${s.comments.length?`<section class="card"><div class="card-head"><h3>Review feedback</h3></div><div class="site-aside-content">${s.comments.map(c=>`<p><strong>${E(c.by)}</strong><br>${E(c.text)}</p>`).join('')}</div></section>`:''}</aside></div>`}
function guidance(s){return {general:'Confirm the Site ID, site type, coordinates, and operator before starting the inspection.',civil:'Check access, foundation condition, corrosion, and the surrounding site. Record observations with supporting photos.',electrical:'Record measurements with their units. Confirm safety precautions before taking live electrical readings.',power:'Capture the installed supply configuration, battery system, generator, and solar equipment.',equipment:'Record model, dimensions, installation height, azimuth, and sector for every item on the tower.',evidence:'Add clear, relevant photos. Preview uploads and assign the correct category before submission.',submission:'Check required fields and review your evidence. Submit a complete record for the technical reviewer.'}[s]}
function field(s,k,label,type='text',options=null,full=false){const v=s.answers[k]??'',lock=s.status==='Approved';return `<div class="field ${full?'full':''}"><label for="f-${k}">${label}</label>${options?`<select id="f-${k}" ${lock?'disabled':''} onchange="saveField('${k}',this.value)">${options.map(o=>`<option ${v===o?'selected':''}>${E(o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${k}" ${lock?'readonly':''} placeholder="Add your field observations…" oninput="saveField('${k}',this.value)">${E(v)}</textarea>`:`<input id="f-${k}" type="${type}" value="${E(v)}" ${lock?'readonly':''} oninput="saveField('${k}',this.value)" ${type==='number'?'min="0" step="any"':''}>`}</div>`}
function workspaceForm(s,locked){let intro=`<p class="form-intro">${guidance(section)}</p>`;if(section==='general')return intro+`<div class="fieldgrid"><div class="field"><label>Site ID</label><input value="${E(s.id)}" readonly><small>Site ID stays consistent across the record and reports.</small></div>${field(s,'siteType','Site type','text',['Tower','Rooftop','Indoor'])}${field(s,'operator','Operator','text',['STC','Mobily','Zain','Other'])}${field(s,'towerHeight','Tower height (m)','number')}${field(s,'surveyDate','Survey date','date')}${field(s,'access','Site access','text',['Accessible','Access restricted','Permit required'])}<div class="field"><label>Latitude</label><input value="${E(s.lat)}" readonly></div><div class="field"><label>Longitude</label><input value="${E(s.lon)}" readonly></div>${field(s,'generalNotes','Survey notes','textarea',null,true)}</div>`;
 if(section==='civil')return intro+[['access','Site access and working area inspected'],['foundation','Foundation condition and visible cracks checked'],['corrosion','Tower members and connections checked for corrosion'],['clearance','Site clearances and surrounding conditions recorded']].map(([k,t])=>`<label class="checkitem"><input type="checkbox" ${s.checks[k]?'checked':''} ${locked?'disabled':''} onchange="saveCheck('${k}',this.checked)"><span>${t}</span></label>`).join('')+`<div style="margin-top:23px">${field(s,'civilNotes','Civil observations','textarea')}</div>`;
 if(section==='electrical')return intro+`<div class="fieldgrid">${field(s,'voltage','AC voltage (V)','number')}${field(s,'dcVoltage','DC system voltage (V)','number')}${field(s,'currentR','Phase R current (A)','number')}${field(s,'currentY','Phase Y current (A)','number')}${field(s,'currentB','Phase B current (A)','number')}${field(s,'powerSource','Power source','text',['Grid supply','Generator','Hybrid','Solar'])}</div><div style="margin-top:23px">${[['earthing','Earthing connections visually inspected'],['labels','Distribution board and circuit labels checked']].map(([k,t])=>`<label class="checkitem"><input type="checkbox" ${s.checks[k]?'checked':''} ${locked?'disabled':''} onchange="saveCheck('${k}',this.checked)"><span>${t}</span></label>`).join('')}${field(s,'electricalNotes','Electrical observations','textarea')}</div>`;
 if(section==='power')return intro+`<div class="fieldgrid">${field(s,'capacity','Rectifier capacity (A)','number')}${field(s,'battery','Battery capacity (Ah)','number')}${field(s,'generator','DG / SG configuration','text',['Not installed','Single generator','Dual generator'])}${field(s,'solar','Solar installation','text',['Not installed','Installed','Planned'])}${field(s,'powerSource','Main power supply','text',['Grid supply','Generator','Hybrid','Solar'])}${field(s,'dcVoltage','DC output voltage (V)','number')}${field(s,'powerNotes','Power system observations','textarea',null,true)}</div>`;
 if(section==='equipment')return intro+`${s.equipment.map((x,i)=>`<div class="card" style="padding:17px;margin-bottom:17px;background:#fbfcf8"><div class="row between" style="margin-bottom:15px"><h3 style="font-size:12px">Equipment ${i+1}</h3>${locked?'':`<button class="btn link danger" onclick="removeEquipment(${i})" aria-label="Remove equipment ${i+1}">${I('trash')}</button>`}</div><div class="fieldgrid">${[['model','Equipment model'],['dimensions','Dimensions L × W × D (m)'],['height','Installation height (m)'],['azimuth','Azimuth (°)'],['sector','Sector / leg']].map(([k,l])=>`<div class="field"><label for="equip-${i}-${k}">${l}</label><input id="equip-${i}-${k}" value="${E(x[k])}" ${locked?'readonly':''} oninput="saveEquipment(${i},'${k}',this.value)"></div>`).join('')}</div></div>`).join('')||'<div class="empty">No equipment recorded yet.</div>'}<button class="btn" ${locked?'disabled':''} onclick="addEquipment()">${I('plus')}Add equipment</button>`;
 if(section==='evidence')return intro+`${locked?'':`<div class="upload-zone" role="button" tabindex="0" onclick="uploadForSite()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();uploadForSite()}">${I('upload')}<h3>Add your site photographs</h3><p>Choose JPG, PNG, or WebP · up to 5 MB each in this preview</p><p>Photos stay on this device. Your original files remain unchanged.</p></div>`}<div class="photo-grid">${s.photos.map((p,i)=>photoCard(s,p,i)).join('')}</div>${s.photos.length?'':'<div class="empty">No photo evidence added yet. Upload a photo to try the redesigned workflow.</div>'}`;
 return intro+submissionContent(s);
}
function submissionContent(s){const missing=missingItems(s),reviewable=role!=='Engineer';return `<div class="card" style="background:#f7faf1;padding:19px;margin-bottom:21px"><div class="row between"><h3 style="font-size:13px">Submission readiness</h3><span class="tag ${missing.length?'orange':'green'}">${missing.length?missing.length+' items to complete':'Ready for review'}</span></div><p class="form-intro" style="margin-bottom:0">${missing.length?missing.map(E).join(' · '):'Required site details, inspection checks, and photo evidence are present.'}</p></div><div class="statline"><span>Site details</span><b>${E(s.id)}</b></div><div class="statline"><span>Survey sections checked</span><b>${Object.values(s.checks).filter(Boolean).length} / 6</b></div><div class="statline"><span>Equipment records</span><b>${s.equipment.length}</b></div><div class="statline"><span>Photo evidence</span><b>${s.photos.length}</b></div><div class="statline"><span>Current status</span>${badge(s.status)}</div><div class="row wrap" style="margin-top:23px"><button class="btn" onclick="printReport()">${I('file')}Print report</button>${s.status==='Approved'?`<span class="tag blue">${I('shield')}Approved record locked</span>`:s.status==='Awaiting review'&&reviewable?`<button class="btn primary" onclick="reviewSite('${E(s.id)}','approve')">${I('check')}Approve survey</button><button class="btn" onclick="reviewSite('${E(s.id)}','changes')">Request changes</button>`:`<button class="btn primary" ${missing.length?'disabled':''} onclick="submitSite()">Submit for review ${I('arrow')}</button>`}</div>${s.status==='Approved'?'<p class="form-intro" style="margin-top:16px;margin-bottom:0">This record is finalized. Changes require a new revision in the connected application.</p>':''}${s.comments.length?`<h3 style="margin-top:26px">Review history</h3>${s.comments.map(c=>`<div style="margin-top:14px;border-left:2px solid #9eba7e;padding-left:13px"><strong style="font-size:11px">${E(c.by)}</strong><p class="form-intro" style="margin:5px 0">${E(c.text)}</p></div>`).join('')}`:''}`}
function missingItems(s){if(s.templateSnapshot)return customMissing(s);let m=[];if(!s.answers.surveyDate)m.push('Survey date');if(!s.answers.towerHeight)m.push('Tower height');if(Object.values(s.checks).filter(Boolean).length<6)m.push('Inspection checks');if(!s.photos.length)m.push('Photo evidence');return m}
function previousSection(){const ix=sections.findIndex(x=>x[0]===section);section=sections[Math.max(0,ix-1)][0];render()}
function nextSection(){const ix=sections.findIndex(x=>x[0]===section);if(ix===sections.length-1)go('overview');else{section=sections[ix+1][0];render();window.scrollTo({top:0,behavior:'smooth'})}}
function saveField(k,v){if(site().status==='Approved')return;site().answers[k]=v;updateProgress();saveChanges()}
function saveCheck(k,v){if(site().status==='Approved')return;site().checks[k]=v;updateProgress();saveChanges()}
function updateProgress(){const s=site();if(s.templateSnapshot){if(s.status!=='Approved'&&s.status!=='Awaiting review')s.progress=customProgress(s);return;}if(s.status==='Approved'||s.status==='Awaiting review')return;const n=[!!s.answers.surveyDate,!!s.answers.towerHeight,...Object.values(s.checks),s.equipment.length>0,s.photos.length>0];s.progress=Math.round(n.filter(Boolean).length/n.length*100);if(s.status==='Draft')s.status='In progress'}
function saveChanges(){const ok=persist();const el=document.getElementById('save-state');if(el){el.innerHTML=I(ok?'check':'help')+(ok?'Saved on this device':'Storage full');el.style.color=ok?'#709148':'#b95849'}}
function saveEquipment(i,k,v){if(site().status==='Approved')return;site().equipment[i][k]=v;saveChanges()}
function addEquipment(){if(site().status==='Approved')return;site().equipment.push({model:'',dimensions:'',height:'',azimuth:'',sector:''});updateProgress();persist();render()}
function removeEquipment(i){if(site().status==='Approved')return;site().equipment.splice(i,1);updateProgress();persist();render();toast('Equipment removed from the saved record')}
function photoCard(s,p,i){return `<article class="photo"><img src="${E(p.src)}" alt="${E(p.name)}" loading="lazy">${s.status!=='Approved'?`<button class="delete-photo" aria-label="Delete ${E(p.name)}" onclick="removePhoto('${E(s.id)}',${i})">×</button>`:''}<div class="photo-meta"><strong>${E(p.name)}</strong><small>${E(s.id)} · ${E(p.category)} · Uploaded locally</small>${s.status!=='Approved'?`<select aria-label="Photo category" onchange="setPhotoCategory('${E(s.id)}',${i},this.value)" style="width:100%;margin-top:9px;border:1px solid var(--line);padding:5px;border-radius:4px;font-size:9px;background:#fafcf5">${['Civil','Tower','Electrical','Power','General'].map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select>`:''}</div></article>`}
function uploadForSite(){if(site().status==='Approved'){toast('Approved records are locked');return}document.getElementById('photo-input').click()}
document.getElementById('photo-input').addEventListener('change',async function(){const s=site();if(s.status==='Approved')return;let added=0;for(const file of this.files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose JPG, PNG, or WebP image files');continue}if(file.size>5*1024*1024){toast('Use photos smaller than 5 MB for this preview');continue}const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)}).catch(()=>null);if(!src)continue;s.photos.push({name:file.name,src,category:'General',fieldId:window.customEvidenceField||''});if(!persist()){s.photos.pop();break}added++}this.value='';window.customEvidenceField='';updateProgress();persist();if(added){addActivity(`${added} photo${added===1?'':'s'} added to ${s.id}`,'camera');toast(`${added} photo${added===1?'':'s'} added`)}render()});
function removePhoto(id,i){const s=data.sites.find(x=>x.id===id);if(s.status==='Approved')return;s.photos.splice(i,1);persist();render();toast('Photo removed')}
function setPhotoCategory(id,i,c){const s=data.sites.find(x=>x.id===id);if(s.status==='Approved')return;s.photos[i].category=c;persist();toast('Photo category updated')}
function submitSite(){const s=site();if(s.status==='Approved'||missingItems(s).length)return;s.status='Awaiting review';s.progress=100;addActivity(`${s.id} submitted for review`,'clipboard');render();toast('Survey submitted. It is now in the review queue.')}
function reviewPage(){const ss=visibleSites().filter(x=>x.status==='Awaiting review');return `${title('Evidence first. Approval next.','Review submitted surveys, record feedback, and keep decisions traceable.',`<button class="btn" onclick="go('sites')">All sites ${I('arrow')}</button>`)}<section class="card"><div class="card-head"><h2>Awaiting technical review</h2><span class="tag orange">${ss.length} submissions</span></div>${ss.map(s=>`<article class="review-card"><div><div class="row"><span class="site-symbol">${I('clipboard')}</span><div><h3>${E(s.id)}</h3><p style="margin-top:5px">${E(s.location)} · ${E(s.engineer)}</p></div></div><div class="review-stats"><span>${I('folder')} ${E(s.project)}</span><span>${I('camera')} ${s.photos.length} photos</span><span>${I('clock')} Sample submission</span></div></div><div class="row"><button class="btn" onclick="openSite('${E(s.id)}','submission')">Review record ${I('arrow')}</button>${role!=='Engineer'?`<button class="btn primary" onclick="reviewSite('${E(s.id)}','approve')">${I('check')}Decide</button>`:''}</div></article>`).join('')||`<div class="empty">${I('check')}Your review queue is clear.<br>Completed submissions will appear here.</div>`}</section>`}
function photosPage(){const ss=visibleSites();let photos=ss.flatMap(s=>s.photos.map((p,i)=>({s,p,i}))).filter(x=>photoFilter==='All'||x.p.category===photoFilter);return `${title('Evidence, organized.','Browse uploaded site photographs by category and open their source record.',`<button class="btn primary" onclick="choosePhotoSite()">${I('upload')}Upload photos</button>`)}<div class="filters"><div class="filter-buttons">${['All','Civil','Tower','Electrical','Power','General'].map(c=>`<button class="${photoFilter===c?'active':''}" onclick="photoFilter='${c}';render()">${c}</button>`).join('')}</div><span class="small muted">${photos.length} uploaded photos</span></div>${photos.length?`<div class="photo-grid">${photos.map(x=>photoCard(x.s,x.p,x.i)).join('')}</div>`:`<section class="card"><div class="empty">${I('camera')}Your photo library is ready.<br>Upload a site photo to explore categories and evidence management.<br><button class="btn primary" style="margin-top:22px" onclick="choosePhotoSite()">${I('upload')}Add site photographs</button></div></section>`}<section class="card" style="margin-top:23px;overflow:hidden"><div class="card-head"><div><h3>Telecom fieldwork reference</h3><p>Image from your supplied application assets · not submitted survey evidence</p></div><span class="tag gray">Reference image</span></div><img src="assets/towers.jpg" alt="Telecommunication towers photographed from below" style="width:100%;height:240px;object-fit:cover;object-position:center 45%;display:block"></section>`}
function reportsPage(){return `${title('The record behind every decision.','Export current survey data or print a site report for review.',`<button class="btn" onclick="exportSites()">${I('export')}Export site register</button>`)}<section class="card"><div class="card-head"><h2>Survey reports</h2><span class="tag gray">Sample workspace</span></div><div class="table-wrap"><table><thead><tr><th>Site ID</th><th>Project</th><th>Status</th><th>Export</th></tr></thead><tbody>${visibleSites().map(s=>`<tr><td><strong>${E(s.id)}</strong></td><td>${E(s.project)}</td><td>${badge(s.status)}</td><td><button class="btn link" onclick="downloadReport('${E(s.id)}')">${I('export')}CSV</button><button class="btn link" onclick="selected='${E(s.id)}';section='submission';go('workspace');printReport()">${I('file')}Print</button></td></tr>`).join('')}</tbody></table></div></section><div class="small muted" style="margin-top:16px">CSV exports use the latest saved preview data. Your existing FDED Excel template can be connected in the Django implementation.</div>`}
function projectsPage(){return `${title('Projects with a clear direction.','Organize site delivery by project, team, and survey status.')}<div class="sites-grid">${['Telecom survey','Network expansion'].map((n,i)=>{const ss=data.sites.filter(s=>s.project===n),done=ss.filter(s=>s.status==='Approved').length;return `<section class="card site-card"><div class="row between"><span class="workspace-icon">${I('folder')}</span><span class="tag green">Demo project</span></div><h3>${n}</h3><p>Central region · Saudi Arabia</p><div class="mini-meta"><span><small>Total sites</small>${ss.length} sites</span><span><small>Approved surveys</small>${done} records</span></div><div class="progress"><span style="width:${done/(ss.length||1)*100}%"></span></div><div class="card-action"><span class="small muted">FDED survey workflow</span><button class="btn link" onclick="siteSearch='${n}';siteFilter='All';go('sites')">Open project ${I('arrow')}</button></div></section>`}).join('')}</div>`}
function teamPage(){return `${title('The right work. The right people.','Explore the proposed role dashboards and responsibilities.')}<section class="card">${[['Admin','AD','Workspace administration','Project configuration, team access, and overall visibility.'],['Team leader','TL','Project coordination & review','Assign sites, review survey evidence, and approve completed records.'],['Engineer','PE','Field surveys & submissions','See assigned sites, complete checklists, and upload photo evidence.']].map(([r,a,t,d])=>`<div class="team-row"><span class="avatar">${a}</span><div class="grow"><strong>${r}</strong><small>${t}</small><small>${d}</small></div><button class="btn ${role===r?'primary':''}" onclick="changeRole('${r}');go('overview')">${role===r?'Current role':'Explore dashboard'}${I('arrow')}</button></div>`).join('')}</section><div class="small muted" style="margin-top:17px">Role switching is a preview feature. Account permissions will be enforced by the connected application.</div>`}
function settingsPage(){return `${title('A workspace that works for you.','Preview preferences and project configuration.')}<div class="settings-grid"><section class="card"><div class="card-head"><h2>Workspace preferences</h2></div><div class="form-body"><div class="statline"><span>Activity notifications</span><button class="toggle ${data.settings.notifications?'on':''}" aria-label="Toggle notifications" aria-pressed="${!!data.settings.notifications}" onclick="data.settings.notifications=!data.settings.notifications;persist();render()"></button></div><div class="statline"><span>Current preview role</span><b>${role}</b></div><div class="statline"><span>Timezone</span><b>Asia / Riyadh</b></div><div class="statline"><span>Measurement units</span><b>m · V · A · Ah · °</b></div></div></section><section class="card"><div class="card-head"><h2>Preview data</h2></div><div class="form-body"><p class="form-intro" style="margin-top:0">Changes and uploads are saved in this browser on this device. This preview is separate from your live survey records.</p><div class="statline"><span>Sample sites</span><b>${data.sites.length}</b></div><div class="statline"><span>Your uploaded photos</span><b>${data.sites.reduce((n,s)=>n+s.photos.length,0)}</b></div><button class="btn danger" style="margin-top:22px" onclick="resetDemo()">${I('trash')}Reset preview data</button></div></section></div>`}
function marketing(){return `<div class="marketing"><div class="preview-banner">REDESIGN PREVIEW · SAMPLE WORKSPACE · EXPLORE THE PROPOSED EXPERIENCE</div><header class="marketing-nav"><a href="#" onclick="go('website');return false"><img src="assets/logo-latest.png" alt="iSurvix"></a><nav class="links"><a href="#workflow">The workflow</a><a href="#solutions">Survey workspace</a><a href="#start">Get started</a><button class="btn dark" onclick="go('overview')">Open workspace ${I('arrow')}</button></nav></header><section class="marketing-hero"><div><div class="eyebrow">ISURVIX SURVEY WORKSPACE</div><h1>Fieldwork.<br>Evidence.<br><span>All connected.</span></h1><p>Site surveys get complicated when photographs, checklists, and approvals live in different places. Give every site one clear, traceable record.</p><div class="row"><button class="btn primary" onclick="go('overview')">Explore the workspace ${I('arrow')}</button><a class="btn link" href="#workflow">See the workflow ${I('down')}</a></div><div class="row muted" style="font-size:10px;margin-top:23px;gap:17px"><span>${I('tower')}Telecom field surveys</span><span>${I('clipboard')}FDED checklists</span></div></div><div class="hero-visual"><img src="assets/towers.jpg" alt="Telecom infrastructure survey reference" style="width:100%;height:170px;object-fit:cover;object-position:center 40%;border-radius:8px;margin-bottom:14px"><div class="mini-screen"><div class="row between"><h3>Your survey workspace</h3><span class="tag green">Demo</span></div><div class="mini-stats"><div>12<small>Assigned sites</small></div><div>04<small>In progress</small></div><div>03<small>Ready for review</small></div></div><div style="border-top:1px solid var(--line);padding-top:17px"><div class="row between small"><strong>DEMO-10452</strong>${badge('In progress')}</div><div class="progress" style="margin:14px 0 8px"><span style="width:68%"></span></div><div class="row between" style="font-size:9px;color:#99a887"><span>Checklist completion</span><b>68%</b></div></div></div><div class="float-card">${I('check')}<div><strong>Evidence stays with the site.</strong><small>Details · Photos · Review history</small></div></div></div></section><div class="market-strip"><span>${I('home')}Civil & site condition</span><span>${I('electric')}Electrical systems</span><span>${I('sun')}Power & solar</span><span>${I('tower')}Tower equipment</span></div><section class="market-section" id="workflow"><div class="row between wrap" style="gap:20px"><h2>Less searching.<br>More site progress.</h2><p style="max-width:380px">A guided journey from site assignment to field evidence and technical review. Everyone knows what comes next.</p></div><div class="market-features"><article class="market-feature">${I('pin')}<div class="eyebrow muted" style="margin-bottom:13px">01 / ASSIGN</div><h3>Start with a clear site.</h3><p>Find the location, assign the engineer, and keep the Site ID consistent through the whole survey.</p></article><article class="market-feature">${I('camera')}<div class="eyebrow muted" style="margin-bottom:13px">02 / SURVEY</div><h3>Capture the full picture.</h3><p>Work through the engineering checklist and attach photographs to the right section of the record.</p></article><article class="market-feature">${I('shield')}<div class="eyebrow muted" style="margin-bottom:13px">03 / REVIEW</div><h3>Make a traceable decision.</h3><p>Review measurements and evidence, request changes, and finalize a complete site survey.</p></article></div></section><section class="market-section" id="solutions"><div class="market-cta" id="start"><div><h2>Your next survey starts here.</h2><p>Explore the dashboard, a guided checklist, and the review experience.</p></div><button class="btn primary" onclick="go('overview')">Open the design preview ${I('arrow')}</button></div></section><footer class="marketing-foot"><span>© 2026 iSurvix · Intelligent Survey Index</span><span>Interactive design concept · Sample data</span></footer></div>`}
function showModal(t,b,f){document.getElementById('dialog-content').innerHTML=`<div class="modal-head"><h2>${t}</h2><button class="iconbtn" onclick="closeModal()" aria-label="Close dialog">${I('close')}</button></div><div class="modal-body">${b}</div><div class="modal-foot">${f||'<button class="btn primary" onclick="closeModal()">Got it</button>'}</div>`;document.getElementById('dialog').showModal()}
function closeModal(){document.getElementById('dialog').close()}
function newSite(){showModal('Create a site',`<p>Add a sample site to try the redesigned assignment workflow.</p><form id="new-site-form" onsubmit="event.preventDefault();createSite()"><div class="field"><label for="new-id">Site ID *</label><input id="new-id" required maxlength="50" placeholder="e.g. DEMO-10600" pattern="[A-Za-z0-9_-]+"><small>Letters, numbers, hyphens, and underscores.</small></div><div class="fieldgrid"><div class="field"><label for="new-lat">Latitude *</label><input id="new-lat" type="number" min="-90" max="90" step="any" value="24.7136" required></div><div class="field"><label for="new-lon">Longitude *</label><input id="new-lon" type="number" min="-180" max="180" step="any" value="46.6753" required></div></div><div class="field" style="margin-top:17px"><label for="new-project">Project</label><select id="new-project"><option>Telecom survey</option><option>Network expansion</option></select></div><div class="field"><label for="new-engineer">Assigned engineer</label><select id="new-engineer"><option>Project engineer</option><option>Field engineer 01</option><option>Field engineer 02</option></select></div></form>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" type="submit" form="new-site-form">${I('plus')}Create site</button>`)}
function createSite(){const id=document.getElementById('new-id').value.trim().toUpperCase(),lat=Number(document.getElementById('new-lat').value),lon=Number(document.getElementById('new-lon').value);if(!id||!/[A-Z0-9_-]+/.test(id)||lat<-90||lat>90||lon<-180||lon>180)return;if(data.sites.some(s=>s.id===id)){toast('That Site ID already exists');return}const s={...seeds()[0],id,lat:lat.toFixed(6),lon:lon.toFixed(6),status:'Draft',progress:0,project:document.getElementById('new-project').value,engineer:document.getElementById('new-engineer').value,equipment:[],checks:blankChecks(),photos:[],comments:[]};s.answers.siteName=id;initTemplateData();const chosen=data.templates.find(t=>t.id===data.projectTemplates[s.project]);if(chosen)bindTemplateToSite(s,chosen);customSection=0;data.sites.unshift(s);addActivity(`${id} created and assigned`,'users');closeModal();openSite(id);toast('Site created. Start with the site details.')}
function showGuide(){showModal('A simple path through your survey',`<p><strong>1. Open a site.</strong><br>Use My sites or select a pin on the illustrative network map.</p><p><strong>2. Complete the checklist.</strong><br>Work through the sections, add equipment, and upload categorized photo evidence. Changes save on this device.</p><p><strong>3. Submit and review.</strong><br>Complete the required inspection checks, then submit. Switch to Team leader to explore the review decision.</p><p><strong>4. Export the record.</strong><br>Download the current data as CSV or print a site report.</p>`)}
function showNotifications(){if(!data.settings.notifications){toast('Activity notifications are turned off in Settings');return}showModal('Workspace activity',`<div class="activity">${activityMarkup()}</div>`)}
function choosePhotoSite(){const ss=visibleSites().filter(s=>s.status!=='Approved');if(!ss.length){toast('No editable sites available');return}showModal('Choose a site for your photographs',`<p>Photos will be attached to this site’s evidence record.</p><div class="field"><label for="upload-site">Site</label><select id="upload-site">${ss.map(s=>`<option value="${E(s.id)}">${E(s.id)} · ${E(s.status)}</option>`).join('')}</select></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="selected=document.getElementById('upload-site').value;closeModal();section='evidence';go('workspace');uploadForSite()">Choose photos ${I('upload')}</button>`)}
function reviewSite(id,action){if(role==='Engineer'){toast('Switch to Team leader or Admin to explore reviews');return}selected=id;const s=site();showModal(action==='approve'?'Record your review decision':'Request changes',`<p>Review <strong>${E(id)}</strong> and leave a clear decision for the field engineer. These are sample records in the design preview.</p><div class="field"><label for="review-action">Decision</label><select id="review-action"><option value="approve" ${action==='approve'?'selected':''}>Approve survey</option><option value="changes" ${action==='changes'?'selected':''}>Request changes</option></select></div><div class="field"><label for="review-comment">Review comment *</label><textarea id="review-comment" placeholder="Explain your decision or specify the corrections needed…"></textarea></div>${!s.photos.length?'<span class="tag orange">Sample record has no uploaded photo evidence</span>':''}`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="commitReview()">Record decision ${I('check')}</button>`)}
function commitReview(){const text=document.getElementById('review-comment').value.trim();if(!text){toast('Add a review comment before recording your decision');return}const action=document.getElementById('review-action').value,s=site();if(action==='approve'&&s.templateSnapshot&&customMissing(s).length){toast('Complete required checklist fields before approval');return;}s.status=action==='approve'?'Approved':'Changes requested';if(action==='approve')s.progress=100;s.comments.push({by:role,text,time:new Date().toISOString()});addActivity(`${s.id} ${action==='approve'?'approved':'returned for changes'}`,action==='approve'?'check':'clipboard');closeModal();render();toast(action==='approve'?'Survey approved. The record is now locked.':'Feedback saved. The survey is open for corrections.')}
function resetDemo(){showModal('Reset your preview?',`<p>This removes locally uploaded photos and changes from this design preview and restores the sample sites. Your original application records are unaffected.</p>`,`<button class="btn" onclick="closeModal()">Keep my changes</button><button class="btn danger" onclick="data={sites:seeds(),activities:[],settings:{compact:false,notifications:true},templates:data.templates,projectTemplates:data.projectTemplates};persist();selected=data.sites[0].id;mapSelected=selected;closeModal();render();toast('Sample workspace restored')">Reset preview</button>`)}
function downloadCSV(name,rows){const enc=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(enc).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('CSV exported from the latest saved data')}
function exportSites(){downloadCSV('iSurvix-sample-site-register.csv',[['Site ID','Location','Latitude','Longitude','Project','Engineer','Status','Progress (%)'],...visibleSites().map(s=>[s.id,s.location,s.lat,s.lon,s.project,s.engineer,s.status,s.progress])])}
function downloadReport(id){const s=data.sites.find(x=>x.id===id);if(s.templateSnapshot){downloadCustomReport(s);return;}downloadCSV(`${s.id}-survey.csv`,[['Section','Field','Value'],['General','Site ID',s.id],['General','Latitude',s.lat],['General','Longitude',s.lon],['General','Status',s.status],...Object.entries(s.answers).map(([k,v])=>['Checklist',k,v]),...Object.entries(s.checks).map(([k,v])=>['Inspection',k,v?'Checked':'Pending']),...s.equipment.flatMap((x,i)=>Object.entries(x).map(([k,v])=>[`Equipment ${i+1}`,k,v])),...s.photos.map(p=>['Photo evidence',p.name,p.category]),...s.comments.map(c=>['Review',c.by,c.text])])}
function printReport(){const s=site();if(s.templateSnapshot){printCustomReport(s);return;}const body=`<!doctype html><html><head><title>${E(s.id)} — Survey Report</title><style>body{font:12px Arial;color:#263520;padding:35px}h1{font-size:24px}h2{font-size:15px;margin-top:28px}p{line-height:1.7}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:9px;text-align:left}th{background:#f3f6ed}img{max-width:220px;max-height:160px;margin:5px}small{color:#8b947d}@media print{button{display:none}}</style></head><body><img src="assets/logo-latest.png" style="width:150px" alt="iSurvix"><h1>${E(s.id)} — Survey report</h1><p>${E(s.project)} · ${E(s.location)} · ${E(s.status)}</p><small>Interactive design preview · Sample data · Generated ${E(new Date().toLocaleDateString('en-GB'))}</small><h2>Site details & measurements</h2><table>${Object.entries(s.answers).map(([k,v])=>`<tr><td>${E(k.replace(/([A-Z])/g,' $1'))}</td><td>${E(v||'—')}</td></tr>`).join('')}</table><h2>Inspection checks</h2><table>${Object.entries(s.checks).map(([k,v])=>`<tr><td>${E(k)}</td><td>${v?'Checked':'Pending'}</td></tr>`).join('')}</table><h2>Tower equipment</h2><table><tr>${['Model','Dimensions (m)','Height (m)','Azimuth (°)','Sector'].map(t=>'<th>'+t+'</th>').join('')}</tr>${s.equipment.map(x=>`<tr>${['model','dimensions','height','azimuth','sector'].map(k=>'<td>'+E(x[k])+'</td>').join('')}</tr>`).join('')}</table><h2>Photo evidence</h2>${s.photos.map(p=>`<div style="display:inline-block"><img src="${E(p.src)}" alt="${E(p.name)}"><p>${E(p.name)} · ${E(p.category)}</p></div>`).join('')||'<p>No photographs added.</p>'}<h2>Review history</h2>${s.comments.map(c=>`<p><strong>${E(c.by)}</strong>: ${E(c.text)}</p>`).join('')||'<p>No review decisions recorded.</p>'}<button onclick="window.print()" style="padding:12px 20px;margin-top:30px">Print / Save PDF</button></body></html>`;const w=window.open('','_blank');if(!w){toast('Allow pop-ups to open the printable report');return}w.document.write(body);w.document.close();w.focus();toast('Printable report opened. Choose Print / Save PDF.')}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}if(e.key==='Escape'&&menuOpen)toggleMenu(false)});
document.getElementById('dialog').addEventListener('click',e=>{if(e.target===document.getElementById('dialog'))closeModal()});
// Initial render runs after the checklist builder extension loads.
